"""Build a compact section ledger from the sampled derived inventory."""
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
rows=json.loads((ROOT/'experiments/anatomy-001.json').read_text())
names={k for r in rows for field in ('breed_sections','master_sections') for k in r[field]}
names.update(('Ball Size Override','Outline Color Override','Fuzz Override','Add Ball Override'))
known={
 'Head Enlargement':'Tested size/spacing and A=100 gate: [HEAD-001](../experiments/head-001.md), [HEAD-002](../experiments/head-002.md)',
 'Move':'Tested reference/default/zero/repeated rows: [MOVE-001](../experiments/move-001.md); native anchoring unresolved',
 'Key Balls':'Master IDs inventoried; section replacement tested: [INHERIT-001](../experiments/inherit-001.md)',
 'Ball Size Override':'Head-only perturbation: [BALL-001](../experiments/ball-001.md)',
 'Color Info Override':'Head-only perturbation: [BALL-001](../experiments/ball-001.md)',
 'Ballz Info':'67 labels per species inventoried; complete column/visual coverage pending: [ANATOMY-001](../experiments/anatomy-001.md)',
 'Eyes':'Master IDs inventoried; dedicated iris/pupil color experiment pending',
 'Project Ball':'Downstream effect observed in MOVE-001; independent field test pending',
 'Default Linez File':'Selected master recorded in provenance; selection/recursion test pending',
}
lines=['# Research coverage ledger','','This is a lower-bound topic inventory, not a complete LNZ specification. It combines six sampled adult breed/master resources with override sections already encountered in code/experiments. More stock breeds, young resources and community references may add topics.','','All controlled editing results currently concern Petz 4 Scottie/Siamese. No topic has native-game validation. Ball-label agreement across versions is asset evidence only.','','| Topic | Current evidence / remaining work |','| --- | --- |']
lines += [f'| {name} | {known.get(name,"Inventoried or implementation lead only; dedicated reference/experiment pending")} |' for name in sorted(names)]
lines += ['','## Species/version matrix','','| Evidence | Dogz 3 | Catz 3 | Dogz 4 | Catz 4 | Dogz 5 | Catz 5 |','| --- | --- | --- | --- | --- | --- | --- |','| Stock render smoke | Passed | Passed | Passed | Passed | Passed | Passed |','| Stock label/key inventory | Sampled | Sampled | Sampled | Sampled | Sampled | Sampled |','| Controlled edits | Pending | Pending | Sampled | Sampled | Pending | Pending |','| Complete per-ball visual map | Pending | Pending | Pending | Pending | Pending | Pending |','| Native-game validation | Pending | Pending | Pending | Pending | Pending | Pending |','','## Next priorities','','1. Iris/pupil fill versus outline experiment and initial eye-editing recipe.','2. Added-ball attachment and head-control interactions.','3. Multi-view base-ball identification with omitted/occluded/utility-ball handling.','4. Another breed per species, followed by edited cross-version checks.','5. Further shape/color/texture/marking sections, growth/variation and design examples.','','Generated by tools/coverage_index.py from derived inventory and explicit evidence links. Update the generator when promoting topic coverage.']
(ROOT/'docs/coverage.md').write_text('\n'.join(lines)+'\n')
